/* Camera playback and evidence-based observations. Credentials stay on the local server. */
const liveState={cameras:[],status:null,panels:new Set(),players:new Set(),main:null,preview:null};
const liveMoney=n=>n==null?'Cost unavailable':'$'+Number(n).toFixed(5);
const liveTime=value=>new Date(value).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});
const liveSection=document.createElement('section');liveSection.id='live-workspace';liveSection.className='live-workspace';
liveSection.innerHTML='<div class="live-heading"><div><span class="eyebrow">CAMERA → OBSERVATION → EVIDENCE</span><h2>A world in motion.<br><span>An agent paying attention.</span></h2><p>Watch the feed. See what the model observes. Inspect the source.</p></div><span class="runtime-badge" id="runtime-status"><i></i> Connecting observation engine</span></div><div id="main-observer"></div><div class="live-wall-heading"><span>CONNECTED CAMERAS</span><span>Live video + provider images · 4 countries</span></div><div class="live-wall" id="live-wall"></div>';
document.querySelector('.intro').after(liveSection);
const previewDialog=document.createElement('dialog');previewDialog.id='agent-preview';previewDialog.innerHTML='<div class="dialog-head"><span class="eyebrow" id="preview-kicker">MISSION PREVIEW</span><button class="close" aria-label="Close agent preview">×</button></div><div id="preview-identity"></div><div id="preview-observer"></div><div class="preview-actions" id="preview-actions"></div>';
document.body.append(previewDialog);previewDialog.querySelector('.close').onclick=()=>previewDialog.close();
previewDialog.addEventListener('close',()=>{liveState.preview?.destroy();liveState.preview=null;});
function createCameraPlayer(host,camera){
  host.innerHTML='<div class="camera-media"><img alt="'+escapeHtml(camera.name)+' provider snapshot"><video muted autoplay playsinline controls aria-label="'+escapeHtml(camera.name)+' live camera"></video><div class="camera-failure" hidden></div></div><div class="player-source"><span class="playback-status">Connecting camera…</span><a href="'+escapeHtml(camera.source)+'" target="_blank" rel="noopener">'+escapeHtml(camera.provider)+' ↗</a>'+(camera.license?'<a href="'+escapeHtml(camera.license)+'" target="_blank" rel="noopener">Licence ↗</a>':'')+'</div>';
  const video=host.querySelector('video'),img=host.querySelector('img'),label=host.querySelector('.playback-status'),error=host.querySelector('.camera-failure');video.muted=true;
  let hls=null,destroyed=false,snapshotTimer,retryTimer,streaming=false,lastMediaRecovery=0,lastProgress=0,lastTime=0,lastClipRefresh=0;
  const snapshot=()=>{if(destroyed||document.hidden)return;img.src=camera.image+'?t='+Math.floor(Date.now()/(camera.interval*1000));};
  const fallback=message=>{streaming=false;video.hidden=true;img.hidden=false;label.textContent=message||'Refreshing image · every '+camera.interval/60+' min';snapshot();};
  img.onload=()=>{error.hidden=true;if(!streaming)label.textContent=(camera.stream?'Video unavailable · ':'')+'Image fetched '+liveTime(Date.now());};
  img.onerror=()=>{if(streaming)return;img.hidden=true;error.hidden=false;error.textContent='Camera temporarily unavailable';label.textContent='Retrying automatically';};
  const play=()=>video.play().catch(()=>{label.textContent='Press play to start video';});
  video.addEventListener('playing',()=>{streaming=true;video.hidden=false;img.hidden=true;error.hidden=true;lastProgress=Date.now();label.textContent=camera.videoClip&&!camera.stream?'↻ Latest clip · loops':'● Live video';});
  video.addEventListener('waiting',()=>{label.textContent=camera.videoClip&&!camera.stream?'Buffering latest clip…':'Buffering live video…';});
  video.addEventListener('timeupdate',()=>{if(video.currentTime!==lastTime){lastTime=video.currentTime;lastProgress=Date.now();}});
  video.addEventListener('pause',()=>{if(!destroyed&&!video.ended)label.textContent='Video paused · press play';});
  function connect(){if(destroyed)return;hls?.destroy();hls=null;video.hidden=false;img.hidden=false;label.textContent=camera.videoClip&&!camera.stream?'Loading latest clip…':'Connecting live video…';
    if(!camera.stream&&camera.videoClip){video.loop=true;lastClipRefresh=Date.now();video.src=camera.videoClip+'?t='+Math.floor(Date.now()/(camera.interval*1000));video.onloadedmetadata=play;video.onerror=()=>fallback('Clip unavailable · refreshing image');return;}if(!camera.stream){video.hidden=true;fallback();return;}
    if(video.canPlayType('application/vnd.apple.mpegurl')&&!window.Hls?.isSupported()){video.src=camera.stream;video.onloadedmetadata=play;video.onerror=()=>{fallback();retryTimer=setTimeout(connect,60000);};}
    else if(window.Hls?.isSupported()){hls=new Hls({maxBufferLength:15,backBufferLength:10});hls.on(Hls.Events.MANIFEST_PARSED,play);hls.on(Hls.Events.ERROR,(_,data)=>{if(!data.fatal)return;host.dataset.playbackError=data.details+(data.response?.code?' HTTP '+data.response.code:'');if(data.type===Hls.ErrorTypes.MEDIA_ERROR&&Date.now()-lastMediaRecovery>10000){lastMediaRecovery=Date.now();hls.recoverMediaError();return;}hls?.destroy();hls=null;fallback();clearTimeout(retryTimer);retryTimer=setTimeout(connect,60000);});hls.loadSource(camera.stream);hls.attachMedia(video);}
    else fallback('Refreshing camera image');
  }
  snapshot();connect();snapshotTimer=setInterval(()=>{if(camera.videoClip&&!camera.stream&&Date.now()-lastClipRefresh>=camera.interval*1000&&!document.hidden)connect();if(!streaming)snapshot();if(streaming&&!video.paused&&Date.now()-lastProgress>45000){fallback('Stream stalled · reconnecting');connect();}},Math.min(camera.interval*1000,30000));
  const player={destroy(){destroyed=true;clearInterval(snapshotTimer);clearTimeout(retryTimer);hls?.destroy();video.pause();video.removeAttribute('src');video.load();img.removeAttribute('src');liveState.players.delete(player);},resume(){if(!streaming)snapshot();}};liveState.players.add(player);return player;
}
function eligibleModel(m){return canSee(m)&&isAgentModel(m)&&!m.id.includes(':batch');}
function createObserver(host,{cameraId='fremont',modelId=liveState.status?.defaultModel||'google/gemma-3-4b-it',brief='Observe roadway conditions, visibility and visible obstructions.',mission=null,autorun=false}={}){
  let camera=liveState.cameras.find(c=>c.id===cameraId),model=catalog.data.find(m=>m.id===modelId),controller=null,player=null,autoTimer=null,report=null,destroyed=false,visible=true,running=false;
  const modelsForSelect=()=>[...catalog.data].filter(eligibleModel).sort((a,b)=>modelName(a).localeCompare(modelName(b)));
  host.innerHTML='<div class="observer-grid"><div class="observer-scene"><div class="observer-toolbar"><span><i class="live-dot"></i> CAMERA FEED</span><select class="observer-camera" aria-label="Observation camera"><option value="">Choose a connected camera</option>'+liveState.cameras.map(c=>'<option value="'+c.id+'">'+escapeHtml(c.name)+' · '+escapeHtml(c.city)+'</option>').join('')+'</select></div><div class="observer-player"></div><div class="observation-sampling"><span>SOURCE OBSERVATION</span><p>AI reads the provider’s still image at its published update interval</p></div></div><div class="observer-analysis"><div class="analysis-title"><span class="model-mark"></span><div><span class="eyebrow">AI OBSERVATION</span><strong class="analysis-model-name"></strong></div><span class="analysis-indicator"></span></div><div class="analysis-select-wrap"><select class="observer-model" aria-label="Observation model">'+(model&&!eligibleModel(model)?'<option value="'+escapeHtml(model.id)+'">'+escapeHtml(modelName(model))+' · no camera image input</option>':'')+modelsForSelect().map(m=>'<option value="'+escapeHtml(m.id)+'">'+escapeHtml(modelName(m))+'</option>').join('')+'</select></div><div class="analysis-phase" role="status"><span class="phase-orb"></span><span>Ready to observe</span></div><div class="analysis-output"><div class="observation-empty"><span>◎</span><h3>Give the agent a moment.</h3><p>A real camera frame. A model you choose.<br>An observation you can inspect.</p></div></div><div class="analysis-evidence" hidden></div><div class="analysis-controls"><button class="button primary observe-now">Analyze camera <span>↗</span></button><label class="auto-observe"><input type="checkbox"> Auto</label><button class="text-button stop-observation" hidden>Stop</button></div><div class="analysis-budget">Checking compute connection…</div></div></div>';
  const q=s=>host.querySelector(s),cameraSelect=q('.observer-camera'),modelSelect=q('.observer-model'),output=q('.analysis-output'),phase=q('.analysis-phase'),evidence=q('.analysis-evidence'),run=q('.observe-now'),auto=q('.auto-observe input'),stop=q('.stop-observation');
  cameraSelect.value=camera?.id||'';modelSelect.value=model?.id||modelId;
  function status(message,busy=false){phase.querySelector('span:last-child').textContent=message;phase.classList.toggle('working',busy);host.classList.toggle('analyzing',busy);}
  function updateBudget(){q('.analysis-budget').textContent=liveState.status?.configured?(liveState.status.providerName||'OpenRouter')+' configured · '+liveMoney(liveState.status.spent)+' / $1 estimated daily spend guard':(liveState.status?.providerName||'OpenRouter')+' unavailable · camera playback remains active';}
  function updateModel(){q('.model-mark').innerHTML=model?logoHtml(model.id):'';q('.analysis-model-name').textContent=model?modelName(model):'Choose a model';run.disabled=!camera||!model||!eligibleModel(model)||!liveState.status?.configured||running;auto.disabled=run.disabled&&!running;}
  function loadCamera(){player?.destroy();if(camera)player=createCameraPlayer(q('.observer-player'),camera);else q('.observer-player').innerHTML='<div class="no-camera"><span>◎</span><h3>Coverage is not connected here yet.</h3><p>Choose one of the connected cameras above to preview the agent.</p></div>';updateModel();}
  function reset(){controller?.abort();controller=null;clearTimeout(autoTimer);running=false;report=null;auto.checked=false;evidence.hidden=true;output.innerHTML='<div class="observation-empty"><span>◎</span><h3>'+(model&&!eligibleModel(model)?'This model cannot view images.':'Ready for the next observation.')+'</h3><p>'+(model&&!eligibleModel(model)?'Choose an image-capable model from the selector above.':'Select Analyze camera to inspect the provider’s current image.')+'</p></div>';status(camera?'Ready to observe':'Choose a connected camera');stop.hidden=true;updateModel();}
  function schedule(){clearTimeout(autoTimer);if(!auto.checked||destroyed||!camera)return;const seconds=camera.interval;q('.analysis-budget').textContent='Auto checks every '+seconds/60+' min while visible · '+liveMoney(liveState.status?.spent)+' / $1 spend guard';autoTimer=setTimeout(()=>{if(!document.hidden&&visible&&(!host.closest('dialog')||previewDialog.open))observe();else schedule();},seconds*1000);}
  function showEvidence(ev){evidence.hidden=false;evidence.innerHTML='<a href="'+escapeHtml(ev.image)+'" target="_blank" rel="noopener" class="evidence-thumb"><img src="'+escapeHtml(ev.image)+'" alt="Exact provider frame analyzed"></a><div><span>SOURCE FRAME · '+escapeHtml(ev.provider)+'</span><b>Retrieved '+liveTime(ev.fetchedAt)+'</b><small>Capture time is printed in the image.</small><button class="export-observation" hidden>Download evidence record ↓</button></div>';}
  async function observe(){
    if(destroyed||running||!camera||!model||!eligibleModel(model)||!liveState.status?.configured)return;
    running=true;report=null;run.disabled=true;stop.hidden=false;run.textContent='Observing…';output.textContent='';evidence.hidden=true;status('Connecting to the observation engine',true);const localController=new AbortController();controller=localController;
    try{const response=await fetch('/api/observe',{method:'POST',signal:localController.signal,headers:{'Content-Type':'application/json','X-Parallax-Token':liveState.status.csrf},body:JSON.stringify({camera:camera.id,model:model.id,brief:brief.slice(0,500)})});if(!response.ok){const problem=await response.json();throw new Error(problem.error||'Observation unavailable');}
      const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',completed=false;
      while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))!==-1){const record=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const event=record.split('\n').find(x=>x.startsWith('event: '))?.slice(7),data=record.split('\n').find(x=>x.startsWith('data: '))?.slice(6);if(!data)continue;const payload=JSON.parse(data);if(destroyed||controller!==localController)return;
        if(event==='phase')status(payload.message,true);
        if(event==='evidence')showEvidence(payload);
        if(event==='token'){output.append(document.createTextNode(payload.text));output.scrollTop=output.scrollHeight;status('Writing the observation',true);}
        if(event==='error')throw new Error(payload.message);
        if(event==='done'){completed=true;report=payload;output.textContent=payload.text.replace(/\*\*(.*?)\*\*/g,(_,v)=>v);liveState.status.spent=payload.spent;status(payload.cached?'Same source frame · saved observation':payload.truncated?'Observation reached its output limit':'Observation complete · human review');showEvidence(payload.evidence);const exportButton=q('.export-observation');exportButton.hidden=false;exportButton.onclick=()=>{const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='parallax-observation-'+report.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};q('.analysis-budget').textContent=(payload.cached?'No new inference charge':liveMoney(payload.cost)+' · '+(payload.tokens||'—')+' tokens')+' · '+escapeHtml(modelName(model));}
      }}if(!completed)throw new Error('The response ended before the observation completed.');
    }catch(error){if(destroyed||controller!==localController)return;if(error.name==='AbortError')status('Observation stopped');else{status(error.message);if(!output.textContent)output.innerHTML='<div class="observation-empty"><span>↻</span><h3>Observation unavailable.</h3><p>'+escapeHtml(error.message)+'</p></div>';auto.checked=false;}}
    finally{if(controller===localController){running=false;controller=null;stop.hidden=true;run.innerHTML='Analyze camera <span>↗</span>';updateModel();schedule();}}
  }
  run.onclick=observe;stop.onclick=()=>{auto.checked=false;controller?.abort();};auto.onchange=()=>{if(auto.checked&&!running)observe();schedule();};
  cameraSelect.onchange=()=>{camera=liveState.cameras.find(c=>c.id===cameraSelect.value);reset();loadCamera();};
  modelSelect.onchange=()=>{model=catalog.data.find(m=>m.id===modelSelect.value);reset();updateModel();};
  const intersection=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;},{threshold:.15});intersection.observe(host);
  const panel={observe,selectCamera(id){cameraSelect.value=id;cameraSelect.onchange();},getModel:()=>model?.id,destroy(){destroyed=true;controller?.abort();player?.destroy();clearTimeout(autoTimer);intersection.disconnect();liveState.panels.delete(panel);}};
  liveState.panels.add(panel);loadCamera();updateBudget();if(!camera||!model||!eligibleModel(model))reset();if(autorun)setTimeout(()=>{if(!destroyed&&!document.hidden&&visible)observe();},1200);return panel;
}
function openAgentPreview({mission=null,modelId=null,cameraId=null}={}){
  if(!liveState.cameras.length){document.querySelector('#toast').textContent='Camera engine is still connecting. Try again shortly.';document.querySelector('#toast').classList.add('show');setTimeout(()=>document.querySelector('#toast').classList.remove('show'),2600);return;}
  liveState.preview?.destroy();modelId=modelId||mission?.modelId||liveState.status?.defaultModel;const model=catalog.data.find(m=>m.id===modelId);
  if(cameraId===null)cameraId=mission?(liveState.cameras.find(c=>c.region===mission.region)?.id||''):'fremont';
  document.querySelector('#preview-kicker').textContent=mission?'MISSION / $'+mission.ticker:'MODEL / OPENROUTER';
  document.querySelector('#preview-identity').innerHTML='<div class="preview-identity">'+(mission?'<span class="preview-coin" style="background:'+escapeHtml(mission.color||'#e5eddb')+'">'+escapeHtml(mission.symbol||mission.name[0])+'</span>':logoHtml(modelId||'openrouter/auto'))+'<div><h2>'+escapeHtml(mission?.name||model&&modelName(model)||modelId)+'</h2><p>'+escapeHtml(mission?.brief||model?.description?.slice(0,210)||'Inspect this model with a connected camera.')+'</p></div></div><div class="preview-meta"><span>'+(mission?(mission.draft?'Local mission draft':'Sample mission')+' · coin not issued':eligibleModel(model||{})?'Image input + text observations':'Capability preview · image analysis unavailable')+'</span><span>'+(model?tokenPrice(model.pricing.prompt)+' in / '+tokenPrice(model.pricing.completion)+' out per 1M tokens':'')+'</span></div>';
  document.querySelector('#preview-actions').innerHTML='<span>AI observations can be wrong. Inspect the original source.</span><button class="button" id="preview-launch">'+(mission?'Use this mission brief':'Launch with this model')+' ↗</button>'+(mission?.draft?'<button class="text-button" id="preview-delete">Delete draft</button>':'');
  document.querySelector('#preview-launch').onclick=()=>{const selected=liveState.preview?.getModel()||modelId;previewDialog.close();openLaunch({...mission,modelId:selected});};
  const deleteButton=document.querySelector('#preview-delete');if(deleteButton)deleteButton.onclick=()=>{try{drafts=drafts.filter(d=>d.id!==mission.id);localStorage.setItem('parallax-drafts',JSON.stringify(drafts));renderRows();previewDialog.close();}catch{deleteButton.textContent='Could not delete draft';}};
  if(!previewDialog.open)previewDialog.showModal();liveState.preview=createObserver(document.querySelector('#preview-observer'),{cameraId,modelId,brief:mission?.brief,mission,autorun:true});
}
openMission=id=>{const mission=[...drafts,...missions].find(m=>m.id===id);if(mission)openAgentPreview({mission});};
window.openModelPreview=id=>openAgentPreview({modelId:id});
// Logo/name previews remain accessible after catalog rerenders.
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-start-model],[data-launch-model],[data-preview-model]');if(trigger){event.preventDefault();event.stopImmediatePropagation();openAgentPreview({modelId:trigger.dataset.startModel||trigger.dataset.launchModel||trigger.dataset.previewModel});}},true);
const intelligenceButton=document.querySelector('#orbio-intelligence-launch');
if(intelligenceButton)intelligenceButton.onclick=()=>window.openOrbioIntegration?window.openOrbioIntegration():openLaunch();
const intelligenceBrand=document.querySelector('#orbio-intelligence-brand');
if(intelligenceBrand)intelligenceBrand.onclick=event=>{if(window.openOrbioIntegration){event.preventDefault();window.openOrbioIntegration();}};
document.querySelector('.ontology').classList.add('animated-ontology','playing');document.querySelectorAll('.graph-line').forEach(n=>n.innerHTML='<span class="signal-packet"></span>');
let regionPlayer=null;loadSnapshot=function(id){clearTimeout(imageExpiry);regionPlayer?.destroy();regionPlayer=null;document.querySelector('#camera-image').onload=null;document.querySelector('#camera-image').onerror=null;document.querySelector('#camera-image').removeAttribute('src');const camera=liveState.cameras.find(c=>c.region===id),host=document.querySelector('.camera-preview');host.querySelector('.region-live-player')?.remove();document.querySelector('#camera-image').hidden=true;document.querySelector('#camera-fallback').hidden=!!camera;document.querySelector('.camera-overlay').hidden=!!camera;if(!camera){document.querySelector('#camera-fallback span').textContent='No connected camera in this region';return;}const holder=document.createElement('div');holder.className='region-live-player';host.append(holder);regionPlayer=createCameraPlayer(holder,camera);document.querySelector('#source-name').textContent=camera.provider+' · '+camera.name;document.querySelector('#source-link').href=camera.source;document.querySelector('#source-footnote').textContent='Open the mission to see an AI observation of the provider’s still image.';};
document.addEventListener('visibilitychange',()=>{if(!document.hidden)liveState.players.forEach(p=>p.resume());});
(async()=>{try{const responses=await Promise.all([fetch('/api/cameras'),fetch('/api/status')]);if(responses.some(r=>!r.ok))throw new Error();const [camerasPayload,status]=await Promise.all(responses.map(r=>r.json()));liveState.cameras=camerasPayload.data;liveState.status=status;document.querySelector('#runtime-status').innerHTML='<i></i> '+(status.configured?escapeHtml(status.providerName||'OpenRouter')+' configured':'Camera playback · AI offline');document.querySelector('#live-wall').innerHTML=liveState.cameras.map(c=>'<article class="live-camera-tile"><div class="wall-player" data-camera-player="'+c.id+'"></div><button class="wall-camera-button" data-preview-camera="'+c.id+'"><span><b>'+escapeHtml(c.name)+'</b><small>'+escapeHtml(c.city)+'</small></span><span>Analyze ↗</span></button></article>').join('');document.querySelectorAll('[data-camera-player]').forEach(h=>createCameraPlayer(h,liveState.cameras.find(c=>c.id===h.dataset.cameraPlayer)));document.querySelectorAll('[data-preview-camera]').forEach(b=>b.onclick=()=>openAgentPreview({cameraId:b.dataset.previewCamera}));window.dispatchEvent(new Event('parallax-ready'));
  }catch{document.querySelector('#runtime-status').textContent='Observation server unavailable';document.querySelector('#main-observer').innerHTML='<div class="runtime-unavailable"><h3>Start the Parallax server to connect the cameras.</h3><p>The live camera and analysis preview needs the included local server.</p></div>';}})();


